function drawAtlas(){if(!baseMap)return;const c=$('atlas'),ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.drawImage(baseMap,0,0,w,h);const placed=[];const points=[...geo.destinations].sort((a,b)=>(a.type==='village'?0:a.type==='peak'?1:2)-(b.type==='village'?0:b.type==='peak'?1:2));for(const p of points){const x=(p.point[0]+10000)/20000*w,y=(p.point[1]+8000)/16000*h;if(placed.some(q=>Math.abs(x-q[0])<55&&Math.abs(y-q[1])<20))continue;placed.push([x,y]);ctx.fillStyle=p.type==='village'?'#906b46':p.type==='peak'?'#697162':'#5c7e6c';ctx.beginPath();ctx.arc(x,y,p.type==='village'?4:2.6,0,Math.PI*2);ctx.fill();ctx.font=p.type==='village'?'16px serif':'13px serif';ctx.textAlign='center';ctx.strokeStyle='#eef0d9';ctx.lineWidth=3;ctx.strokeText(p.name,x,y-8);ctx.fillStyle='#4b6652';ctx.fillText(p.name,x,y-8);}playerArrow(ctx,(player.x+10000)/20000*w,(player.z+8000)/16000*h,12);}
